import{_ as t,o as n,c as s,a0 as o}from"./chunks/framework.ChlVJx0I.js";const r="/pi-extensions/assets/pruning-settings.DzlH6TVz.png",g=JSON.parse('{"title":"pruning extension","description":"","frontmatter":{},"headers":[],"relativePath":"extensions/pruning.md","filePath":"extensions/pruning.md","lastUpdated":1789775493000}'),a={name:"extensions/pruning.md"};function i(l,e,c,d,h,u){return n(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="pruning-extension" tabindex="-1">pruning extension <a class="header-anchor" href="#pruning-extension" aria-label="Permalink to &quot;pruning extension&quot;">​</a></h1><p>Two-level context control. Pruning is the first level, in front of pi&#39;s native compaction. When the context estimate reaches pi&#39;s own compaction threshold (the context window minus <code>reserveTokens</code>), pruning replaces the large tool outputs in the outgoing request with short references: a file pointer for <code>read</code> outputs, a shell summary for <code>bash</code> outputs, and a plain marker for everything else. The full outputs stay in the session file, which is never modified (<a href="/pi-extensions/adr/0011-pruning-is-a-request-projection.html">ADR 0011</a>). No LLM call is involved: the first level costs zero tokens.</p><p>When pi is about to compact on the threshold, the <strong>prune gate</strong> decides: if the context estimate after pruning is at most the window minus twice <code>reserveTokens</code>, pruning wins and the compaction is cancelled. Otherwise pi&#39;s native compaction runs unchanged as the second level. A <code>recall</code> tool resolves any recall reference back to the full output.</p><h2 id="screenshot" tabindex="-1">Screenshot <a class="header-anchor" href="#screenshot" aria-label="Permalink to &quot;Screenshot&quot;">​</a></h2><p>The <code>/pruning settings</code> display: the active settings and the current prune state, in dim text under the last message.</p><p><img src="'+r+'" alt="pruning settings display"></p><h2 id="behavior" tabindex="-1">Behavior <a class="header-anchor" href="#behavior" aria-label="Permalink to &quot;Behavior&quot;">​</a></h2><ul><li><strong>Engagement.</strong> Pruning engages the first time the context estimate exceeds <code>contextWindow - reserveTokens</code>, the same threshold and the same effective window (context window cap included) that pi&#39;s own compaction and footer read. The estimate uses pi&#39;s token helpers: the last assistant usage plus a character estimate for the messages after it. Engagement is sticky for the session (<a href="/pi-extensions/adr/0018-pruning-engagement-is-sticky.html">ADR 0018</a>): once it has engaged, it keeps engaging on every later request until a reset, so the outgoing prefix holds one shape and the provider&#39;s prompt cache stays hot. A reset is a compaction that runs (the raw size drops) or a session start, after which the session runs raw again until it re-crosses the threshold.</li><li><strong>Eligibility.</strong> Tool result and bash execution outputs whose size estimate exceeds <code>minResultTokens</code>. With <code>protectCurrentTurn</code> set, outputs after the last user message are never pruned. Image content parts are never replaced.</li><li><strong>Markers.</strong><ul><li><code>read</code>: the file path, the line range read, the size, an instruction to re-read with the read tool, and the recall reference for the exact old content.</li><li><code>bash</code>: the command, exit code, total line count, size, the first 10 lines, an omission note, the last 10 lines, and the recall reference. Summary lines are capped at 200 characters so one long line cannot make the marker as large as the output.</li><li>other tools: the tool name, the size, and the recall reference.</li></ul></li><li><strong>Recall references.</strong> The line number of the result entry in the session file, permanent and branch-independent, so references keep resolving across forks and tree navigation. In an ephemeral session (no session file) the marker carries the 12 character entry id instead. The recall tool accepts both forms regardless of which the marker carries.</li><li><strong>Re-derivation.</strong> The pruned view is a pure function of the current messages and thresholds, re-derived on every request and never written to the session file. The only session state is the sticky Engagement flag (<a href="/pi-extensions/adr/0018-pruning-engagement-is-sticky.html">ADR 0018</a>); a restart or resume recomputes the same pruned projection, and the flag resets with the session.</li><li><strong>Settling.</strong> After one request goes out pruned, the provider reports usage for the pruned size and the estimate drops back below the threshold, but the sticky Engagement flag holds it pruned, so there is no per-turn settling and no pruned/raw alternation (<a href="/pi-extensions/adr/0018-pruning-engagement-is-sticky.html">ADR 0018</a>). The gate still settles on its own: it runs a fresh prune pass against the window minus twice the reserve.</li><li><strong>Second level.</strong> pi&#39;s compaction summarizes from the raw session entries and never sees the markers, so pruning never degrades summary quality. Manual <code>/compact</code> and context overflow recovery always perform a real compaction; the gate acts only on the threshold reason.</li><li><strong>Notifications.</strong> One info notification per session, when pruning first activates. No further notifications while it is stably active.</li></ul><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>The <code>pruning</code> section of the settings files. The project <code>&lt;cwd&gt;/.pi/settings.json</code> overrides the global settings, key by key.</p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>enabled</code></td><td><code>true</code></td><td>Turn the first level on or off.</td></tr><tr><td><code>minResultTokens</code></td><td><code>1000</code></td><td>A tool output smaller than this is never pruned.</td></tr><tr><td><code>protectCurrentTurn</code></td><td><code>true</code></td><td>Never prune outputs after the last user message.</td></tr></tbody></table><p><code>compaction.enabled</code> and <code>compaction.reserveTokens</code> stay pi&#39;s own settings. The two levels are independently switchable: <code>pruning.enabled</code> for the first level, <code>compaction.enabled</code> for the second. When auto-compaction is off, the gate never fires, but the context hook keeps pruning on its own switch.</p><h2 id="command" tabindex="-1">Command <a class="header-anchor" href="#command" aria-label="Permalink to &quot;Command&quot;">​</a></h2><p><code>/pruning settings [key=value ...]</code></p><ul><li>No args: shows the three keys and a read-only state line (outputs pruned, tokens saved per request, last gate decision), then opens a picker to edit one key.</li><li><code>enabled=true|false</code>, <code>minResultTokens=N</code>, <code>protectCurrentTurn=true|false</code>: sets the keys and persists them to the project settings file when one exists, else the global file.</li></ul><h2 id="recall-tool" tabindex="-1">Recall tool <a class="header-anchor" href="#recall-tool" aria-label="Permalink to &quot;Recall tool&quot;">​</a></h2><p><code>recall</code> with one argument, <code>ref</code>:</p><ul><li><code>#&lt;line&gt;</code> - the default form: up to 12000 characters plus a hint pointing at the full form.</li><li><code>#&lt;line&gt;:full</code> - uncapped.</li><li>an entry id, with the same optional <code>:full</code> suffix.</li></ul><p>Only tool result entries resolve; any other entry type is an error. A recall result is itself a tool output and is prune-eligible under the same rules; its marker points at the original entry.</p>',19)])])}const m=t(a,[["render",i]]);export{g as __pageData,m as default};
